<?php
namespace App\Http\Controllers;
use App\Models\{Cart,CartItem,Category,Discount,Food,Order,OrderItem,Payment,Address,InventoryTransaction}; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB; use Illuminate\Support\Str;
class CustomerController extends Controller {
 public function home(){return view('customer.home',['featured'=>Food::where('is_available',true)->where('is_featured',true)->take(6)->get(),'categories'=>Category::where('is_active',true)->get()]);}
 public function menu(Request $r){$foods=Food::with('category')->where('is_available',true)->when($r->q,fn($q,$v)=>$q->where('name','like',"%$v%"))->when($r->category,fn($q,$v)=>$q->where('category_id',$v))->paginate(12);return view('customer.menu',compact('foods'));}
 private function cart(Request $r){return Cart::firstOrCreate(['user_id'=>$r->user()->id]);}
 public function cartView(Request $r){$cart=$this->cart($r)->load('items.food');return view('customer.cart',compact('cart'));}
 public function addCart(Request $r,Food $food){$d=$r->validate(['quantity'=>'required|integer|min:1|max:20']);abort_unless($food->is_available && $food->quantity >= $d['quantity'],422,'Not enough stock.');$cart=$this->cart($r);$item=CartItem::firstOrNew(['cart_id'=>$cart->id,'food_id'=>$food->id]);$item->quantity=($item->exists?$item->quantity:0)+$d['quantity'];abort_if($item->quantity>$food->quantity,422,'Quantity exceeds current stock.');$item->save();return back()->with('success','Added to cart.');}
 public function updateCart(Request $r,CartItem $item){abort_unless($item->cart->user_id===$r->user()->id,403);$d=$r->validate(['quantity'=>'required|integer|min:1']);abort_if($d['quantity']>$item->food->quantity,422,'Quantity exceeds stock.');$item->update($d);return back()->with('success','Cart updated.');}
 public function removeCart(Request $r,CartItem $item){abort_unless($item->cart->user_id===$r->user()->id,403);$item->delete();return back()->with('success','Item removed.');}
 public function checkout(Request $r){$cart=$this->cart($r)->load('items.food');abort_if($cart->items->isEmpty(),422,'Cart is empty.');return view('customer.checkout',compact('cart'));}
 public function placeOrder(Request $r){$d=$r->validate(['customer_name'=>'required|max:120','phone'=>'required|max:30','order_type'=>'required|in:dine_in,takeout,delivery','delivery_address'=>'required_if:order_type,delivery|nullable|max:500','payment_method'=>'required|in:cod,cash_pickup,gcash','payment_reference'=>'required_if:payment_method,gcash|nullable|max:100','special_instructions'=>'nullable|max:1000','discount_code'=>'nullable|max:40']);$user=$r->user();$order=DB::transaction(function() use($r,$d,$user){$cart=$this->cart($r)->load('items.food');abort_if($cart->items->isEmpty(),422,'Cart is empty.');$subtotal=0;foreach($cart->items as $item){$food=Food::lockForUpdate()->findOrFail($item->food_id);abort_if(!$food->is_available||$food->quantity<$item->quantity,422,"{$food->name} is no longer available in that quantity.");$subtotal+=$food->price*$item->quantity;}$discount=null;$discountAmount=0;if(!empty($d['discount_code'])){$discount=Discount::where('code',strtoupper($d['discount_code']))->lockForUpdate()->first();abort_unless($discount&&$discount->validFor($subtotal),422,'Discount code is invalid.');$discountAmount=$discount->type==='percent'?round($subtotal*$discount->value/100,2):min($subtotal,$discount->value);}$fee=$d['order_type']==='delivery'?50:0;$o=Order::create(['order_number'=>'ROS-'.now()->format('Ymd').'-'.strtoupper(Str::random(6)),'user_id'=>$user->id,'discount_id'=>$discount?->id,'customer_name'=>$d['customer_name'],'phone'=>$d['phone'],'delivery_address'=>$d['delivery_address']??null,'order_type'=>$d['order_type'],'subtotal'=>$subtotal,'discount_amount'=>$discountAmount,'delivery_fee'=>$fee,'total'=>$subtotal-$discountAmount+$fee,'special_instructions'=>$d['special_instructions']??null]);foreach($cart->items as $item){$food=Food::lockForUpdate()->findOrFail($item->food_id);OrderItem::create(['order_id'=>$o->id,'food_id'=>$food->id,'food_name'=>$food->name,'unit_price'=>$food->price,'quantity'=>$item->quantity,'line_total'=>$food->price*$item->quantity]);}Payment::create(['order_id'=>$o->id,'method'=>$d['payment_method'],'reference'=>$d['payment_reference']??null,'amount'=>$o->total]);$cart->items()->delete();return $o;});return redirect()->route('orders.show',$order)->with('success','Order placed. We will confirm it shortly.');}
 public function orders(Request $r){$orders=$r->user()->orders()->latest()->paginate(12);return view('customer.orders',compact('orders'));} public function showOrder(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id,403);$order->load('items','payment');return view('customer.order',compact('order'));}
 public function cancel(Request $r,Order $order){abort_unless($order->user_id===$r->user()->id&&$order->status==='pending',403);$order->update(['status'=>'cancelled']);return back()->with('success','Order cancelled.');}
}
